      "te": "పృథుని కుమారుడా, ఓ అర్జునా, నపుంసకత్వానికి లొంగకు. అది నీకు తగదు. గుండె యొక్క ఈ అర్ధ బలహీనతను వదిలించుకోండి! లేచి నిలబడు, ఓ శత్రువులను జయించినవాడా!",
      "hi": "हे पृथानन्दन अर्जुन ! इस नपुंसकताको मत प्राप्त हो; क्योंकि तुम्हारेमें यह उचित नहीं है। हे परंतप ! हृदयकी इस तुच्छ दुर्बलताका त्याग करके युद्धके लिये खड़े हो जाओ।",
      "sa": "क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते।\n\nक्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप।।2.3।।",
