    "teluguMeaning": "ఈ శరీరంలో దేహికి బాల్యము, యౌవనము, వృద్ధాప్యము ఎలా కలుగుతాయో, అలాగే మరొక శరీర ప్రాప్తి కూడా జరుగుతుంది. వివేకి దీనికి మోహితుడు కాడు.",
