      "te": "ఈ శరీరంలో దేహికి బాల్యము, యౌవనము, వృద్ధాప్యము ఎలా కలుగుతాయో, అలాగే మరొక శరీర ప్రాప్తి కూడా జరుగుతుంది. వివేకి దీనికి మోహితుడు కాడు.",
      "hi": "देहधारीके इस मनुष्यशरीरमें जैसे बालकपन, जवानी और वृद्धावस्था होती है, ऐसे ही देहान्तरकी प्राप्ति होती है। उस विषयमें धीर मनुष्य मोहित नहीं होता।",
      "sa": "देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा।\n\nतथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति।।2.13।।",
      "gu": "આ શ્લોકમાં બાળપણ, યુવાની અને વૃદ્ધાવસ્થાનો ઉલ્લેખ થાય છે. આત્મા આ તબક્કાઓને શરીર દ્વારા અનુભવે છે, જે દર્શાવે છે કે શરીર ક્ષણિક અને પરિવર્તનશીલ છે.",
      "ta": null,
