    "sanskrit": "मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः।\n\nआगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत।।2.14।।",
    "transliteration": "mātrā-sparśhās tu kaunteya śhītoṣhṇa-sukha-duḥkha-dāḥ\nāgamāpāyino ’nityās tans-titikṣhasva bhārata",
    "wordMeanings": "mātrā-sparśhāḥ—contact of the senses with the sense objects; tu—indeed; kaunteya—Arjun, the son of Kunti; śhīta—winter; uṣhṇa—summer; sukha—happiness; duḥkha—distress; dāḥ—give; āgama—come; apāyinaḥ—go; anityāḥ—non-permanent; tān—them; titikṣhasva—tolerate; bhārata—descendant of the Bharat",
    "translation": "The contact of the senses with the objects, O son of Kunti, which causes heat and cold, pleasure and pain, has a beginning and an end; they are impermanent; endure them bravely, O Arjuna.",
    "meaning": "2.14 मात्रास्पर्शाः contacts of senses with objects? तु indeed? कौन्तेय O Kaunteya (son of Kunti)? शीतोष्णसुखदुःखदाः producers of cold and heat? pleasure and pain? आगमापायिनः with beginning and end? अनित्याः impermanent? तान् them? तितिक्षस्व bear (thou)? भारत O Bharata.Commentary -- Cold is pleasant at one time and painful at another. Heat is pleasant in winter but painful in summer.",
    "teluguTranslation": "ఓ కుంతీ పుత్రా! ఇంద్రియ విషయాల సంపర్కం శీతోష్ణాలను, సుఖదుఃఖాలను ఇస్తుంది. అవి వచ్చేవి, పోయేవి, అశాశ్వతమైనవి. వాటిని ఓర్పుతో సహించు.",
