      "hi": "कारण कि हे पुरुषोंमें श्रेष्ठ अर्जुन! सुख-दुःखमें सम रहनेवाले जिस धीर मनुष्यको ये मात्रास्पर्श (पदार्थ) व्यथित (सुखी-दुःखी) नहीं कर पाते, वह अमर होनेमें समर्थ हो जाता है अर्थात् वह अमर हो जाता है।",
      "sa": "यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ।\n\nसमदुःखसुखं धीरं सोऽमृतत्वाय कल्पते।।2.15।।",
      "gu": "અહીં 'સમદુખસુખં' નો અર્થ છે દુઃખ અને સુખ બંનેને સમાન રીતે જોવું, એટલે કે જ્યારે કોઈ વ્યક્તિ દુઃખ અને સુખને સમાન દૃષ્ટિથી જોઈ શકે અને તેના મનનો સંતુલન બગાડતો નથી, ત્યારે તે સમદુખસુખં માનવ કહેવાય છે.",
