    "teluguMeaning": "ఆత్మను ఆయుధాలు ఛేదించలేవు, అగ్ని దహించలేదు, నీరు తడపలేదు, వాయువు ఆర్పలేదు.",
    "iast": "nainaṁ chhindanti śhastrāṇi nainaṁ dahati pāvakaḥ\nna chainaṁ kledayantyāpo na śhoṣhayati mārutaḥ",
