      "te": "కానీ నీవు దానిని నిరంతరం పుట్టి, చచ్చిపోతున్నట్లు భావించినా, ఓ పరాక్రమవంతుడా, నీవు దుఃఖించకూడదు.",
      "hi": "हे महाबाहो ! अगर तुम इस देहीको नित्य पैदा होनेवाला अथवा नित्य मरनेवाला भी मानो, तो भी तुम्हें इस प्रकार शोक नहीं करना चाहिये।",
      "sa": "अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम्।\n\nतथापि त्वं महाबाहो नैवं शोचितुमर्हसि।।2.26।।",
      "gu": "શ્રીકૃષ્ણ કહે છે કે જો આત્માને સતત જન્મ લેતી (‘નિત્યજાતં’) અને સતત મૃત્યુ પામતી (‘નિત્યં માન્યસે મૃતમ્’) માનીએ, તો પણ શોક કરવો યોગ્ય નથી. કૃષ્ણ અર્જુનને સમજાવે છે કે જીવન અને મૃત્યુ સ્વાભાવિક પ્રક્રિયા છે અને તેમ માટે વ્યથિત થવું જ્ઞાનસંગત નથી. આથી તેઓ અર્જુનને કર્તવ્યપાલનમાં સ્થિર રહેવા પ્રેરિત કરે છે.",
