      "hi": "हे भारत ! सभी प्राणी जन्मसे पहले अप्रकट थे और मरनेके बाद अप्रकट हो जायँगे, केवल बीचमें ही प्रकट दीखते हैं। अतः इसमें शोक करनेकी बात ही क्या है?",
      "sa": "अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत।\n\nअव्यक्तनिधनान्येव तत्र का परिदेवना।।2.28।।",
      "gu": "કૃષ્ણ કહે છે કે બધા જીવોના જીવનની શરૂઆત અવ્યક્ત (અપ્રગટ) સ્વરૂપમાં થાય છે, પછી માત્ર થોડા સમય માટે જ તેઓ વ્યક્ત (પ્રગટ) થાય છે અને ત્યારબાદ ફરીથી અવ્યક્તમાં વિલીન થઇ જાય છે. આથી, જીવનું અસ્તિત્વ માત્ર વચ્ચેના સમયગાળા માટે જ દેખાય છે.",
      "ta": null,
