      "gu": "‘આશ્ચર્યવત્’ શબ્દનો ત્રણ વખત ઉપયોગ આત્માને જોયા માટે, તેના વિષે બોલવા માટે અને તેના વિષે સાંભળવા માટે કરવામાં આવ્યો છે. આથી દર્શાવવામાં આવે છે કે આત્માનું તત્ત્વજ્ઞાન સામાન્ય બાબત નથી – તે અતિ દુર્લભ અને આશ્ચર્યજનક છે. ઘણા લોકો આત્માને જુએ છે, તેના વિષે ચર્ચા કરે છે અથવા સાંભળે છે, પરંતુ થોડા જ લોકો તેને સાચી રીતે સમજવામાં સફળ થાય છે. આ શ્લોક આપણને આત્મજ્ઞાનના મહત્ત્વ અને તેની દુર્લભતા વિશે જાગૃત કરે છે.",
