      "hi": "अपने स्वधर्म (क्षात्रधर्म) को देखकर भी तुम्हें विकम्पित अर्थात् कर्तव्य-कर्मसे विचलित नहीं होना चाहिये; क्योंकि धर्ममय युद्धसे बढ़कर क्षत्रियके लिये दूसरा कोई कल्याणकारक कर्म नहीं है।",
      "sa": "स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि।\n\nधर्म्याद्धि युद्धाछ्रेयोऽन्यत्क्षत्रियस्य न विद्यते।।2.31।।",
      "gu": "કૃષ્ણ અર્જુનને પોતાના સ્વધર્મ, એટલે કે પોતાનો જાતિ અનુરૂપ કર્તવ્ય—અહીં ક્ષત્રિય તરીકેનું કર્તવ્ય—પાલન કરવા માટે કહે છે. કૃષ્ણ કહે છે કે ક્ષત્રિય માટે ધર્મયુક્ત યુદ્ધ કરતાં શ્રેષ્ઠ બીજું કંઈ નથી. આથી, અર્જુને પોતાના શૌર્ય અને કર્તવ્યથી ડગમગાવું નહીં જોઈએ.",
      "ta": null,
