      "gu": "કૃષ્ણ કહે છે કે નિષ્કામ કર્મના માર્ગમાં કરેલો પ્રયત્ન ક્યારેય વ્યર્થ નથી જતો. ભલે થોડો પણ પ્રયત્ન કરવામાં આવે, તેનો લાભ જરૂર મળે છે. આ માર્ગમાં એની મહેનત કદી નષ્ટ થતી નથી.",
