      "en": "Full of desires, with heaven as their goal, (they speak words that are directed to ends) leading to new births as the result of their works, and prescribe various methods abounding in specific actions, for the attainment of pleasure and power.",
      "te": "కోరికలతో నిండిన, స్వర్గాన్ని తమ లక్ష్యంగా పెట్టుకుని, (అవి చివరలకు దిశానిర్దేశం చేసే పదాలు మాట్లాడతాయి) వారి పనుల ఫలితంగా కొత్త జన్మలకు దారితీస్తాయి మరియు ఆనందం మరియు శక్తిని పొందడం కోసం నిర్దిష్ట చర్యలలో పుష్కలంగా ఉన్న వివిధ పద్ధతులను నిర్దేశిస్తాయి.",
      "hi": "-- 2.43।। हे पृथानन्दन ! जो कामनाओंमें तन्मय हो रहे हैं, स्वर्गको ही श्रेष्ठ माननेवाले हैं, वेदोंमें कहे हुए सकाम कर्मोंमें प्रीति रखनेवाले हैं, भोगोंके सिवाय और कुछ है ही नहीं - ऐसा कहनेवाले हैं, वे अविवेकी मनुष्य इस प्रकारकी जिस पुष्पित (दिखाऊ शोभायुक्त) वाणीको कहा करते हैं, जो कि जन्मरूपी कर्मफलको देनेवाली है तथा भोग और ऐश्वर्यकी प्राप्तिके लिये बहुतसी क्रियाओंका वर्णन करनेवाली है।",
      "sa": "कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम्।\n\nक्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति।।2.43।।",
      "gu": "કામાત્મા લોકો એ એવા લોકો છે, જેઓની અંદર ઇચ્છાઓ પ્રબળ હોય છે અને જેઓનું મુખ્ય લક્ષ્ય સ્વર્ગ પ્રાપ્ત કરવું છે. તેઓ જીવનમાં માત્ર ભોગ અને વૈભવ મેળવવા માટે વિવિધ ધાર્મિક ક્રિયામાં વ્યસ્ત રહે છે. આ લોકો ફળોની આશા રાખીને કર્મ કરે છે અને પુનર્જન્મ તથા કર્મના ફળોને મહત્વ આપે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
