      "en": "The Vedas deal with the three attributes; be thou above these three attributes. O Arjuna, free yourself from the pairs of opposites and ever remain in the quality of Sattva, freed from acquisition and preservation, and be established in the Self.",
      "te": "వేదాలు మూడు లక్షణాలతో వ్యవహరిస్తాయి; నీవు ఈ మూడు గుణముల పైన ఉండుము. ఓ అర్జునా, వైరుధ్యాల జంటల నుండి మిమ్మల్ని మీరు విడిపించుకోండి మరియు సత్వగుణం యొక్క గుణాన్ని కలిగి ఉండండి, సముపార్జన మరియు సంరక్షణ నుండి విముక్తి పొందండి మరియు ఆత్మలో స్థిరపడండి.",
      "hi": "वेद तीनों गुणोंके कार्यका ही वर्णन करनेवाले हैं; हे अर्जुन! तू तीनों गुणोंसे रहित हो जा, निर्द्वन्द्व हो जा, निरन्तर नित्य वस्तु परमात्मा में स्थित हो जा, योगक्षेमकी चाहना भी मत रख और परमात्मपरायण हो जा।",
      "sa": "त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन।\n\nनिर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान्।।2.45।।",
      "gu": "કૃષ્ણ અર્જુનને ઉપદેશ આપે છે કે તેણે ત્રણ ગુણો – સત્વ, રજસ અને તમસ –ના પ્રભાવમાંથી ઉપર ઉઠવું જોઈએ. તેઓ સમજાવે છે કે વેદોમાં વર્ણવાયેલા ભોગ અને સાધનો મુખ્યત્વે ત્રૈગુણ્ય (ત્રણ ગુણોની ક્રિયાઓ) સાથે સંબંધિત છે અને મનુષ્યને સંસારિક બંધનમાં જ રાખે છે. તેથી, અર્જુનને સૂચના આપવામાં આવે છે કે તે આ ત્રીગુણાત્મક વિષયોમાં આસક્ત ન થાય અને આત્મતત્ત્વ પર સ્થિર રહે. આ રીતે મનુષ્ય સાચા આધ્યાત્મિક વિકાસ તરફ આગળ વધી શકે છે અને મુક્તિ પ્રાપ્ત કરી શકે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
