      "gu": "અહીં સર્વતઃ સમ્પ્લુતોદકનું અર્થ છે કે દરેક તરફથી ભરાયેલા મોટા જળાશય અને ઉદપાન એટલે નાના પાણીના કુવા. આ ઉપમા દ્વારા બતાવવામાં આવ્યું છે કે મોટા જળાશય મળ્યા પછી નાના કૂવામાં પાણી લેવા કોઈ જ જરૂર રહેતી નથી, તે જ રીતે, યથાર્થ જ્ઞાન પ્રાપ્ત કરનાર માટે પૂર્ણતા પ્રાપ્ત થાય છે.",
