      "te": "సమత్వ బుద్ధితో కూడినవాడు ఇక్కడే పుణ్యపాపాలు రెండింటినీ త్యజిస్తాడు. కాబట్టి యోగాన్ని ఆశ్రయించు. కర్మలలో కుశలతే (నైపుణ్యమే) యోగము.",
      "hi": "बुद्धि-(समता) से युक्त मनुष्य यहाँ जीवित अवस्थामें ही पुण्य और पाप दोनोंका त्याग कर देता है। अतः तू योग-(समता-) में लग जा, क्योंकि योग ही कर्मोंमें कुशलता है।",
      "sa": "बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते।\n\nतस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम्।।2.50।।",
      "gu": "કૃષ્ણ કહે છે કે જે વ્યક્તિ સમબુદ્ધિ ધરાવે છે, તે આ જીવનમાં સારા અને ખરાબ કર્મ બંનેને ત્યજી શકે છે. તે વ્યક્તિ પુણ્ય અને પાપથી ઉપર ઊભી રહી શકે છે. આવા મનુષ્ય માટે કર્મોનું બંધન રહીતું નથી.",
