    "teluguMeaning": "మీరు చదివిన వేద గ్రంధాలచే కలవరపడిన మీ బుద్ధి ఎప్పుడైతే చలించకుండా స్థిరంగా నిలచిందో, అప్పుడు మీరు ఆత్మసాక్షాత్కారాన్ని పొందుతారు.",
    "iast": "śhruti-vipratipannā te yadā sthāsyati niśhchalā\nsamādhāv-achalā buddhis tadā yogam avāpsyasi",
    "translations": {
      "en": "When your intellect, which is perplexed by the Vedic texts you have read, stands immovable and steady in the Self, then you will attain Self-realization.",
      "te": "మీరు చదివిన వేద గ్రంధాలచే కలవరపడిన మీ బుద్ధి ఎప్పుడైతే చలించకుండా స్థిరంగా నిలచిందో, అప్పుడు మీరు ఆత్మసాక్షాత్కారాన్ని పొందుతారు.",
      "hi": "जिस कालमें शास्त्रीय मतभेदोंसे विचलित हुई तेरी बुद्धि निश्चल हो जायगी और परमात्मामें अचल हो जायगी, उस कालमें तू योगको प्राप्त हो जायगा।",
      "sa": "श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला।\n\nसमाधावचला बुद्धिस्तदा योगमवाप्स्यसि।।2.53।।",
      "gu": "કૃષ્ણ કહે છે કે જ્યારે મનુષ્યની બુદ્ધિ વિવિધ વચનો અને ઉપદેશોથી ગુંચવાઈ જાય છે, ત્યારે તેને 'શ્રુતિ વિપ્રતિપન્ના' કહેવામાં આવે છે. આ અર્થ છે કે વ્યક્તિ અનેક મતભેદો અને શંકાઓથી ઘેરાયેલી હોય છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "जिस कालमें शास्त्रीय मतभेदोंसे विचलित हुई तेरी बुद्धि निश्चल हो जायगी और परमात्मामें अचल हो जायगी, उस कालमें तू योगको प्राप्त हो जायगा।",
    "englishTranslation": "When your intellect, which is perplexed by the Vedic texts you have read, stands immovable and steady in the Self, then you will attain Self-realization."
