      "en": "Arjuna said, \"O Krishna, what is the description of one who has steady wisdom and is merged in the superconscious state? How does one of steady wisdom speak, how do they sit, and how do they walk?\"",
      "te": "అర్జునుడు, \"ఓ కృష్ణా, స్థిరమైన జ్ఞానాన్ని కలిగి ఉండి, అతీంద్రియ స్థితిలో విలీనమైన వ్యక్తి యొక్క వర్ణన ఏమిటి? స్థిరమైన జ్ఞానం ఉన్నవాడు ఎలా మాట్లాడతాడు, వారు ఎలా కూర్చుంటారు మరియు ఎలా నడుచుకుంటారు?\"",
      "hi": "अर्जुन बोले - हे केशव ! परमात्मामें स्थित स्थिर बुद्धिवाले मनुष्यके क्या लक्षण होते हैं? वह स्थिर बुद्धिवाला मनुष्य कैसे बोलता है, कैसे बैठता है और कैसे चलता है?",
      "sa": "अर्जुन उवाच\n\nस्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव।\n\nस्थितधीः किं प्रभाषेत किमासीत व्रजेत किम्।।2.54।।",
      "gu": "અર્જુને કૃષ્ણને પૂછ્યું છે કેમ કે તે જીવનમાં સાચા શાંતિ અને સ્થિરતા મેળવવાની પ્રક્રિયા સમજી શકતો નથી. તેણે ચિંતન કર્યું કે જે વ્યક્તિ જ્યાં મન સંપૂર્ણ શાંત છે, તેવી સ્થિતિમાં પહોંચી જાય છે, તેનું વર્તન કેવું હોય છે. તે જીવનના માર્ગદર્શન માટે માર્ગદર્શન માંગે છે.",
