      "te": "ఎప్పుడైతే, తాబేలు తన అవయవాలన్నింటినీ అన్ని వైపులా ఉపసంహరించుకుంటుంది, అతను ఇంద్రియ వస్తువుల నుండి తన ఇంద్రియాలను ఉపసంహరించుకుంటాడు, అప్పుడు అతని జ్ఞానం స్థిరంగా ఉంటుంది.",
      "hi": "जिस तरह कछुआ अपने अङ्गोंको सब ओरसे समेट लेता है, ऐसे ही जिस कालमें यह कर्मयोगी इन्द्रियोंके विषयोंसे इन्द्रियोंको सब प्रकारसे समेट लेता (हटा लेता) है, तब उसकी बुद्धि प्रतिष्ठित हो जाती है।",
      "sa": "यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः।\n\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता।।2.58।।",
      "gu": "આ શ્લોકમાં કૃષ્ણે કૂર્મ, એટલે કે કાચબાની ઉપમા આપી છે. જેમ કાચબું પોતાની અંગોને સર્વ દિશામાંથી અંદર ખેંચી લે છે, તેમ જ મનુષ્યે પોતાની ઇન્દ્રિયોને ઇન્દ્રિયાર્થોથી દૂર ખેંચવી જોઈએ.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
