      "te": "అల్లకల్లోలమైన ఇంద్రియాలు, ఓ అర్జునా, వాటిని నియంత్రించడానికి ప్రయత్నిస్తున్నప్పటికీ, తెలివైన వ్యక్తి యొక్క మనస్సును హింసాత్మకంగా తీసుకువెళతాయి.",
      "hi": "हे कुन्तीनन्दन! (रसबुद्धि रहनेसे) यत्न करते हुए विद्वान् मनुष्यकी भी प्रमथनशील इन्द्रियाँ उसके मनको बलपूर्वक हर लेती हैं।",
      "sa": "यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः।\n\nइन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः।।2.60।।",
