      "hi": "जैसे सम्पूर्ण नदियोंका जल चारों ओरसे जलद्वारा परिपूर्ण समुद्रमें आकर मिलता है, पर समुद्र अपनी मर्यादामें अचल प्रतिष्ठित रहता है ऐसे ही सम्पूर्ण भोग-पदार्थ जिस संयमी मनुष्य को विकार उत्पन्न किये बिना ही उसको प्राप्त होते हैं, वही मनुष्य परमशान्तिको प्राप्त होता है, भोगोंकी कामनावाला नहीं।",
      "sa": "आपूर्यमाणमचलप्रतिष्ठं\n\nसमुद्रमापः प्रविशन्ति यद्वत्।\n\nतद्वत्कामा यं प्रविशन्ति सर्वे\n\nस शान्तिमाप्नोति न कामकामी।।2.70।।",
      "gu": "આ ઉપમાનમાં, કૃષ્ણ કહે છે કે અનેક નદીઓના પાણી સમુદ્રમાં મળી જાય છે છતાં પણ સમુદ્ર અચળ અને સ્થિર રહે છે. એ જ રીતે, જે પુરુષ કોઈ પણ ભોગવાસનાઓ આવવા છતાં આંતરિક રીતે અવિચલિત રહે છે, તે જ સાચી શાંતિ પ્રાપ્ત કરે છે.",
